function run(input) {
  try {

    const data = typeof input === "string" ? JSON.parse(input) : input;

    if (!data) return "";

    const street = data.street && data.street !== "null" ? data.street : "";
    const number = data.street_number && data.street_number !== "null" ? data.street_number : "";
    const neighborhood = data.neighborhood && data.neighborhood !== "null" ? data.neighborhood : "";
    const city = data.city && data.city !== "null" ? data.city : "";
    const uf = data.federative_unit && data.federative_unit !== "null" ? data.federative_unit : "";
    const zip = data.zip_code && data.zip_code !== "null" ? data.zip_code : "";
    const complement = data.complements && data.complements !== "null" ? data.complements : "";

    let endereco = "";

    if (street) {
      endereco += street;
      if (number) endereco += ", " + number;
    }

    if (complement) {
      endereco += " - " + complement;
    }

    if (neighborhood) {
      endereco += endereco ? " - " + neighborhood : neighborhood;
    }

    if (city || uf) {
      const cidadeUf = [city, uf].filter(Boolean).join("/");
      endereco += endereco ? " - " + cidadeUf : cidadeUf;
    }

    if (zip) {
      endereco += endereco ? " - CEP: " + zip : "CEP: " + zip;
    }

    return endereco;

  } catch (e) {
    return "";
  }
}

