function run(input) {
    try {
        const data = typeof input === "string"
            ? JSON.parse(input)
            : input;

        if (
            !data ||
            !data.records ||
            !Array.isArray(data.records) ||
            data.records.length === 0
        ) {
            return JSON.stringify({
                quantidade: 0,
                CaseNumber: "",
                CreatedDate: ""
            });
        }

        const records = data.records;

        function calcularTempo(createdDate) {
            if (!createdDate) {
                return "";
            }

            const dataCriacao = new Date(createdDate);
            const agora = new Date();

            const diferencaMs = agora.getTime() - dataCriacao.getTime();

            if (diferencaMs < 0) {
                return "";
            }

            const horas = diferencaMs / (1000 * 60 * 60);

            if (horas < 24) {
                return "há menos de um dia";
            }

            const dias = Math.floor(horas / 24);

            if (dias === 1) {
                return "há um dia";
            }

            return "há " + dias + " dias";
        }

        // Pega os CaseNumbers
        const caseNumbers = records
            .map(function (record) {
                return record.CaseNumber || "";
            })
            .filter(function (valor) {
                return valor !== "";
            });

        // Busca a data mais antiga
        let dataMaisAntiga = null;

        records.forEach(function (record) {
            if (!record.CreatedDate) {
                return;
            }

            const dataAtual = new Date(record.CreatedDate);

            if (
                !dataMaisAntiga ||
                dataAtual.getTime() < dataMaisAntiga.getTime()
            ) {
                dataMaisAntiga = dataAtual;
            }
        });

        const tempoMaisAntigo = dataMaisAntiga
            ? calcularTempo(dataMaisAntiga)
            : "";

        return JSON.stringify({
            quantidade: caseNumbers.length,
            CaseNumber: caseNumbers.join(", "),
            CreatedDate: tempoMaisAntigo
        });

    } catch (e) {
        return JSON.stringify({
            error: true,
            message: "Erro ao processar resposta",
            details: e.message
        });
    }
}

function run(input) {
    try {
        const data = typeof input === "string"
            ? JSON.parse(input)
            : input;

        if (
            !data ||
            !data.records ||
            !Array.isArray(data.records) ||
            data.records.length === 0
        ) {
            return "";
        }

        function mascararEmail(email) {
            // Caso não tenha e-mail
            if (!email || typeof email !== "string") {
                return "****ail@.com";
            }

            // Extrai o e-mail caso venha no formato:
            // [email@dominio.com](mailto:email@dominio.com)
            const emailMatch = email.match(
                /[A-Za-z0-9._%+-]+@[A-Za-z0-9.-]+\.[A-Za-z]{2,}/
            );

            if (!emailMatch) {
                return "****ail@.com";
            }

            const emailLimpo = emailMatch[0];

            const partes = emailLimpo.split("@");

            if (partes.length !== 2) {
                return "****ail@.com";
            }

            const usuario = partes[0];
            const dominio = partes[1];

            let finalUsuario;

            if (usuario.length <= 2) {
                finalUsuario = usuario;
            } else {
                finalUsuario = usuario.slice(-2);
            }

            return "***" + finalUsuario + "@" + dominio;
        }

        const resultado = data.records.map(function (record) {
            const emailMascarado = mascararEmail(record.Email);

            const funcao = record.Status__c
                ? String(record.Status__c).trim()
                : "";

            return emailMascarado + " - " + funcao;
        });

        return resultado.join("\n");

    } catch (e) {
        return "";
    }
}

